/* =====================================================================
 *  robot.c  -  Autocar line follower + Bluetooth manual control
 *
 *  Blue Pill (STM32F103C8) with HAL, project generated by STM32CubeMX.
 *  Settings: robot_config.h      Hardware handles come from main.c.
 *
 *  BIG PICTURE
 *    Robot_Loop() runs every LOOP_MS milliseconds:
 *      1. read the buttons            -> start/stop, change mode
 *      2. read the 4 line sensors     -> which ones see the line
 *      3. run the current mode        -> decide wheel speeds
 *      4. move the servo a small step -> smooth, never jerky
 *      5. update LEDs, print debug text
 * ===================================================================== */
